"use client";
import { useEffect, useRef } from "react";
import { typeScrollParent, useTypeLoop, type TypographyMotionProps } from "./typography-shared";
export interface VelocityTypeProps extends Omit<TypographyMotionProps, "trigger"> {
  intensity?: number;
  damping?: number;
  maxVelocity?: number;
  minWeight?: number;
  maxWeight?: number;
  minWidth?: number;
  maxWidth?: number;
  maxSlant?: number;
  onVelocityChange?: (velocity: number) => void;
}
/** Works with variable fonts; scale and skew preserve the response for static fonts. */
export function VelocityType({
  text = "Momentum",
  intensity = 1,
  damping = 0.13,
  duration = 0.6,
  maxVelocity = 2200,
  minWeight = 400,
  maxWeight = 950,
  minWidth = 100,
  maxWidth = 140,
  maxSlant = 12,
  className,
  style,
  replayKey,
  onVelocityChange,
}: VelocityTypeProps) {
  const root = useRef<HTMLDivElement>(null),
    velocity = useRef({ target: 0, value: 0, lastTime: 0, lastY: 0, eventTime: 0 });
  useEffect(() => {
    const element = root.current!;
    const parent = typeScrollParent(element);
    const source = parent ?? window;
    const read = () => parent?.scrollTop ?? window.scrollY;
    const state = velocity.current;
    state.lastY = read();
    state.lastTime = performance.now();
    const scroll = () => {
      const now = performance.now(),
        y = read();
      state.target = Math.max(
        -maxVelocity,
        Math.min(maxVelocity, ((y - state.lastY) / Math.max(8, now - state.lastTime)) * 1000),
      );
      state.lastY = y;
      state.lastTime = now;
      state.eventTime = now;
    };
    source.addEventListener("scroll", scroll, { passive: true });
    return () => source.removeEventListener("scroll", scroll);
  }, [maxVelocity]);
  useTypeLoop(
    root,
    (_time, delta, reduced) => {
      const state = velocity.current;
      if (performance.now() - state.eventTime > 70) state.target *= 0.78;
      state.value +=
        (state.target - state.value) *
        (1 -
          Math.pow(
            1 - Math.max(0.01, Math.min(0.9, damping)),
            delta / ((16.67 * Math.max(0.05, duration)) / 0.6),
          ));
      const signed = reduced
          ? 0
          : Math.max(-1, Math.min(1, (state.value / Math.max(1, maxVelocity)) * intensity)),
        amount = Math.abs(signed);
      const el = root.current!;
      el.style.fontVariationSettings = `"wght" ${minWeight + (maxWeight - minWeight) * amount}, "wdth" ${minWidth + (maxWidth - minWidth) * amount}, "slnt" ${-signed * maxSlant}`;
      el.style.transform = `scaleX(${1 + amount * 0.16}) skewX(${-signed * maxSlant}deg)`;
      el.dataset.velocity = String(reduced ? 0 : state.value);
      onVelocityChange?.(reduced ? 0 : state.value);
    },
    replayKey ?? "",
  );
  return (
    <div
      ref={root}
      className={className}
      style={{
        display: "inline-block",
        transformOrigin: "50% 50%",
        fontWeight: minWeight,
        ...style,
      }}
      data-typography="velocity-type"
    >
      {text}
    </div>
  );
}
